mapper.select:
SELECT GCM.generic_key AS genericKey, GCM.key_comment AS keyComment, GCM.type_key AS typeKey, GCM.type_comment AS typeComment, GCM.code, GCM.code_comment AS codeComment, GCM.value_1 AS value1, GCM.is_active AS isActive FROM generic_code_master GCM
AND GCM.generic_key = #{genericKey}
AND GCM.type_key = #{type}
AND GCM.code = #{code}
AND GCM.is_active = #{isActive}
ORDER BY GCM.generic_key , GCM.sort_order
